mapper.select:
SELECT g.id AS goodsId, COALESCE(inv.quantity, 0) AS bookQty, COALESCE(inv.cost_price, 0) AS costPrice FROM goods g LEFT JOIN inventory inv ON inv.goods_id = g.id
AND g.category_id IN #{cid}
AND g.id IN #{gid}
AND g.status = 1 AND ( COALESCE(inv.quantity, 0) <= 0 OR COALESCE(inv.quantity, 0) <= g.safety_stock_lower OR (g.safety_stock_upper IS NOT NULL AND COALESCE(inv.quantity, 0) >= g.safety_stock_upper) )
AND 1 = 0
ORDER BY g.id
